with feeders as (
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , cast(null as varchar) as ENDORSEMENT_NUMBER
        , ENDORSEMENT_DATE as ENDORSEMENT_DATE
        , cast(null as varchar) as ENDORSEMENT_TYPE
        , cast(null as varchar) as EFFECTIVE_DATE
        , cast(null as varchar) as ENDORSEMENT_REASON
        , cast(null as varchar) as ENDORSEMENT_SUB_TYPE
        , cast(null as varchar) as PREMIUM_IMPACT_AMOUNT
        , cast(null as varchar) as STAMP_DUTY_ON_ENDORSEMENT
        , 'BJAZ_HM_MEMBER_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_member_dtls') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__POLICY_REF))) as HUB_POLICY_HK
        , cast(null as varchar) as ENDORSEMENT_NUMBER
        , ENDTPASS_ON as ENDORSEMENT_DATE
        , ENDT_TYPE as ENDORSEMENT_TYPE
        , ENDT_EFF_DATE as EFFECTIVE_DATE
        , cast(null as varchar) as ENDORSEMENT_REASON
        , cast(null as varchar) as ENDORSEMENT_SUB_TYPE
        , cast(null as varchar) as PREMIUM_IMPACT_AMOUNT
        , cast(null as varchar) as STAMP_DUTY_ON_ENDORSEMENT
        , 'BJAZ_PMJAY_PRMBOOK_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_pmjay_prmbook_dtls') }}
    where (nullif(trim(POLICY_REF),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , coalesce(nullif(trim(ENDORSEMENT_NO), ''), '') as ENDORSEMENT_NUMBER
        , cast(null as varchar) as ENDORSEMENT_DATE
        , cast(null as varchar) as ENDORSEMENT_TYPE
        , cast(null as varchar) as EFFECTIVE_DATE
        , ENDORSE_REASON as ENDORSEMENT_REASON
        , ENDORSE_SUB_TYPE as ENDORSEMENT_SUB_TYPE
        , cast(null as varchar) as PREMIUM_IMPACT_AMOUNT
        , cast(null as varchar) as STAMP_DUTY_ON_ENDORSEMENT
        , 'BJAZ_VERSIONS_EXTN' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_versions_extn') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , cast(null as varchar) as ENDORSEMENT_NUMBER
        , cast(null as varchar) as ENDORSEMENT_DATE
        , cast(null as varchar) as ENDORSEMENT_TYPE
        , cast(null as varchar) as EFFECTIVE_DATE
        , ENDT_REASON as ENDORSEMENT_REASON
        , cast(null as varchar) as ENDORSEMENT_SUB_TYPE
        , cast(null as varchar) as PREMIUM_IMPACT_AMOUNT
        , cast(null as varchar) as STAMP_DUTY_ON_ENDORSEMENT
        , 'BJAZ_POLICY_SUMMARY' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_policy_summary') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , cast(null as varchar) as ENDORSEMENT_NUMBER
        , cast(null as varchar) as ENDORSEMENT_DATE
        , cast(null as varchar) as ENDORSEMENT_TYPE
        , cast(null as varchar) as EFFECTIVE_DATE
        , cast(null as varchar) as ENDORSEMENT_REASON
        , cast(null as varchar) as ENDORSEMENT_SUB_TYPE
        , ENDORSE_PREMIUM as PREMIUM_IMPACT_AMOUNT
        , ENDORSE_STAMP_AMT as STAMP_DUTY_ON_ENDORSEMENT
        , 'BJAZ_POLICY_BASES_EXTN' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_policy_bases_extn') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
),

resolved as (
    select
        HUB_POLICY_HK,
        ENDORSEMENT_NUMBER,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ENDORSEMENT_DATE end) as ENDORSEMENT_DATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ENDORSEMENT_TYPE end) as ENDORSEMENT_TYPE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then EFFECTIVE_DATE end) as EFFECTIVE_DATE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then ENDORSEMENT_REASON end) as ENDORSEMENT_REASON,
        max(case when SOURCE_RUN = 'opus_health_delta3' then ENDORSEMENT_SUB_TYPE end) as ENDORSEMENT_SUB_TYPE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then PREMIUM_IMPACT_AMOUNT end) as PREMIUM_IMPACT_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_delta3' then STAMP_DUTY_ON_ENDORSEMENT end) as STAMP_DUTY_ON_ENDORSEMENT,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_POLICY_HK, ENDORSEMENT_NUMBER
),

hashed as (
    select
        *,
        case when ENDORSEMENT_NUMBER is not null or ENDORSEMENT_DATE is not null or ENDORSEMENT_TYPE is not null or EFFECTIVE_DATE is not null or ENDORSEMENT_REASON is not null or ENDORSEMENT_SUB_TYPE is not null or PREMIUM_IMPACT_AMOUNT is not null or STAMP_DUTY_ON_ENDORSEMENT is not null
                     then md5(upper(coalesce(cast(ENDORSEMENT_NUMBER as varchar), '') || '|' || coalesce(cast(ENDORSEMENT_DATE as varchar), '') || '|' || coalesce(cast(ENDORSEMENT_TYPE as varchar), '') || '|' || coalesce(cast(EFFECTIVE_DATE as varchar), '') || '|' || coalesce(cast(ENDORSEMENT_REASON as varchar), '') || '|' || coalesce(cast(ENDORSEMENT_SUB_TYPE as varchar), '') || '|' || coalesce(cast(PREMIUM_IMPACT_AMOUNT as varchar), '') || '|' || coalesce(cast(STAMP_DUTY_ON_ENDORSEMENT as varchar), '')))
                end as SAT_POLICY_ENDORSEMENT_HASHDIFF
    from resolved
)

select * from hashed
where HUB_POLICY_HK is not null
  and SAT_POLICY_ENDORSEMENT_HASHDIFF is not null
